def major_vowel_harmony(word: str) -> bool:
    back_vowels = 'aıou'
    front_vowels = 'eiöü'
    vowels = [char for char in word if char in back_vowels + front_vowels]
    if len(vowels) < 2:
        return True
    return all(char in back_vowels for char in vowels) or all(char in front_vowels for char in vowels)
```

