def number_to_turkish(n: int) -> str:
    units = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
    tens = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'dokuzyüz']
    hundreds = ['', 'yüz', 'ikiyüz', 'üçyüz', 'dörtyüz', 'beşyüz', 'altıyüz', 'yüzyetmiş', 'yüzseksen', 'yüz dokuzyüz']

    if n == 0:
        return 'sıfır'

    if n < 10:
        return units[n]

    if n < 100:
        if n % 10 == 0:
            return tens[n // 10]
        else:
            return tens[n // 10] + ' ' + units[n % 10]

    if n < 1000:
        if n % 100 == 0:
            return hundreds[n // 100]
        else:
            return hundreds[n // 100] + ' ' + number_to_turkish(n % 100)
```

