def longest_balanced_prefix(s: str) -> int:
    balance = 0
    max_length = 0
    for i, char in enumerate(s):
        if char == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            break
        if balance == 0:
            max_length = i + 1
    return max_length
